# 数据文件：src/components/permissions/PermissionDecisionDebugInfo.tsx
# slug = src_components_permissions_PermissionDecisionDebugInfo_tsx
# 规则：一个源文件 = 一个数据文件；中文用三引号；禁止英文双引号 " 与反斜杠 \（用「」/『』代替）。
ANNOTATIONS = [
    (1, 'before', '''本文件是权限决策的「法医报告」：当用户想知道某条命令为什么被允许、为什么被拦、为什么弹了框，这里把决策原因、建议、以及「你写的规则里哪些永远不会生效」逐条摊开。四个组件由内到外：原因转文字、原因条目、建议规则摘要、建议明细。整份文件的技术看点有两个——一是决策原因有十种类型，每种都要翻成人话；二是复合命令把原因做成了递归结构，渲染时必须自己处理嵌套。'''),
    (17, 'before', '''原因条目的属性：可选的标题（用来在调试面板里加一行小标题）加上必填的决策原因。标题可选是因为同一个组件既用于顶层原因，也用于子命令的缩进原因，后者不需要再加标题。'''),
    (21, 'before', '''把决策原因翻成一行可读文字。函数签名的类型约束很值得注意：它把「子命令结果」这一种从入参类型里排除掉了——也就是说这个函数只负责叶子原因，复合原因由调用方自己递归。这种「在类型层面禁掉递归分支」的做法，比在函数体里加一句判断要可靠得多。'''),
    (24, 'before', '''分类器原因在进入 switch 之前被单独拦掉：只有在两个特性开关任一开启时才认这种类型。之所以不放进 switch，是因为它依赖编译期特性开关，如果放进 switch，外部构建里会留下一个永不命中的分支。'''),
    (27, 'before', '''十种原因的翻译表。结构上分成三类：带具体规则或工具名的（规则、权限提示工具、钩子），带模式名的（模式），以及只有一段自由文本的（工作目录、安全检查、其他、异步代理）。读的时候注意每种类型的输出都尽量包含「是什么」与「从哪来」两个信息，这是让用户能自己动手修的前提。'''),
    (29, 'before', '''规则类原因同时给出规则内容与来源（本地设置、项目设置、用户设置等），来源被翻成小写短语。用户看到「来自项目设置」就能立刻想到去哪个文件改，这是这条信息存在的全部意义。'''),
    (41, 'before', '''钩子类原因是唯一「有原因则带原因、无原因则只报名字」的分支：钩子可以只返回允许或拒绝而不解释，此时不该拼出一个空的冒号。这类细节在调试信息里尤其重要，因为空字符串会让用户以为信息丢了。'''),
    (49, 'before', '''原因条目组件：先取主题（用于给对勾与叉号上色），再按类型分派到两种渲染——子命令结果走递归列表，其余走一行文字。整个组件只有一个记忆化槽包住格式化函数，其余都是把结果拼进盒子。'''),
    (59, 'before', '''这里第二层分派只处理两类：子命令结果与其它。注意子命令结果这一支返回的是列表，每一项自己又是一行「图标加子命令」，若该子命令还有自己的原因就再缩进一层继续递归——递归的终止条件由上面那个把子命令结果排除掉的类型约束保证。'''),
    (60, 'before', '''子命令结果分支：把结果映射成「条目数组」再逐条渲染。用 Array.from 包一层而不是直接遍历映射，是因为底层是映射结构而不是普通对象，直接展开拿不到键值对。'''),
    (64, 'before', '''每条子命令的图标由行为决定：允许给对勾并用成功色，其余给叉号并用错误色。注意颜色是通过主题函数算出来的着色器包在图形常量外面，而不是给文本加颜色属性——这是因为图标本身是字符串，只有包一层着色才能上色。'''),
    (65, 'before', '''单条子命令的渲染：第一行是「图标加子命令原文」，第二行是可选的原因（缩进两个空格加一个转角符号），第三行是可选的建议规则。三层都用同一个纵向盒子叠起来，所以整块读起来像一棵树。缩进用的是空格字面量而不是内边距，是为了让转角符号与上一层严格对齐。'''),
    (108, 'before', '''建议规则摘要组件：把建议里的规则提取出来，用逗号连成一行，前面加转角符号。如果一条规则都提不出来就整体返回空——注意这里用的是「早期返回哨兵」而不是普通的提前 return，因为组件的记忆化槽必须在所有路径上被填满，哨兵就是编译器表达提前返回的方式。'''),
    (120, 'before', '''进入哨兵区：先放哨兵，再在带标签的块里做真正的判断。块结束前如果命中「空规则」就把哨兵换成空值，之后统一在块外检查哨兵——这就是编译器改写提前返回的固定形态，读的时候把「哨兵赋值」当成 return 即可。'''),
    (124, 'before', '''规则为空时直接置空值并跳出：没有规则就没有摘要行，不渲染空壳。'''),
    (157, 'before', '''哨兵检查：只要哨兵被替换过（即走了提前返回那条路），就直接返回那个值。这一句之后的所有代码都只在「没有提前返回」时执行。'''),
    (192, 'before', '''从权限更新里抽目录：只认「添加目录」这一种更新类型，其余全部丢弃。用扁平映射一次拿完，因为一条更新可能带多个目录。'''),
    (205, 'before', '''从权限更新里抽模式：取最后一条设模式更新。用「取最后」而不是「取第一」，语义是后写的覆盖先写的，与设置文件的合并规则一致。'''),
    (210, 'before', '''建议明细组件：把一份建议拆成三类来展示——规则、目录、模式。组件开头先处理「完全没有建议」的情况，中间处理「三类都为空」的情况，最后才是正常的分类列表。前两种情况文案不同（复数与单数），这个差别来自「用户是否提供了建议」而不是「建议里有没有内容」，读的时候别把两者混为一谈。'''),
    (216, 'before', '''完全没有建议时的渲染：右侧对齐的「建议」标签加上一个「无」。这里没有提前返回，而是构造完直接返回，因为这一段不需要走后面的记忆化路径。'''),
    (257, 'before', '''三类都为空的分支：结构与上面几乎相同，唯一区别是标签用了单数。这条分支存在的理由是——建议对象存在但内容全空，说明后端明确给了「没有可建议的东西」，与「压根没给建议」是两种状态，调试时要能分辨。'''),
    (321, 'before', '''正常路径的主拼装：先算标签行，再按「有规则就加规则段、有目录就加目录段、有模式就加模式段」拼三段。三段各自用同一个宽度做右对齐，所以整块看起来像一张两列表格——左列标签右对齐、右列内容左对齐，这在终端里是最省字符的对齐方案。'''),
    (342, 'before', '''调试信息主组件。它做四件事：取权限上下文、从决策里分离出原因与建议、算出「哪些规则永远不生效」、再把四行信息加一个警告块纵向排开。四行分别是行为、消息（仅非允许时）、原因、建议。'''),
    (348, 'before', '''权限上下文从全局状态里取一个切片。取切片而不是整个状态，是为了让这个组件只在权限上下文变化时重渲染，而不是全局状态一动就重渲染。'''),
    (354, 'before', '''沙箱自动允许：只有当沙箱启用且「沙箱内自动允许」也被打开时才算成立。这个值参与不可达规则的计算，因为沙箱自动允许会让一批显式规则变得多余。'''),
    (359, 'before', '''过滤优先级第一档：如果这次决策带了建议规则，就只保留「与建议规则同名同内容」的不可达规则。语义是——用户正要添加的这条规则已经存在，于是新加的这条永远不会生效，这个提示最有价值，所以优先级最高。'''),
    (363, 'before', '''过滤优先级第二档：没有建议时，若给了工具名，就只看这个工具下的不可达规则。第三档是两者都没有，全部展示。三档的共同点是都会先算出全量再过滤，而不是在计算阶段就带条件——先全量后过滤让计算函数保持无参数分支。'''),
    (387, 'before', '''行为行：右对齐的标签加左对齐的值。标签宽度固定为十，正好容下这几个标签里最长的那个，于是所有行天然对齐。'''),
    (401, 'before', '''消息行只在行为不是允许时出现：允许的决策没有消息可看，渲染一行空标签反而干扰。'''),
    (425, 'before', '''建议行固定渲染，宽度与标签宽度一致，这样即使没有建议也会显示一个「无」，保持整块的行数稳定。'''),
    (433, 'before', '''不可达规则块：只有存在时才多留一段上边距并画一个警告标题（带数量），然后逐条展开。每条又分三行——规则内容用警告色、原因压暗、修复建议压暗并带前缀。这种「问题、为什么、怎么修」的三行结构，是调试类提示里信息密度最高的排法。'''),
    (454, 'before', '''单条不可达规则的渲染：三行都要缩进两格，且原因与修复建议用两个空格字面量而不是内边距，理由与前面的树形对齐一致——终端里只有空格能保证跨组件严格对齐。'''),
]
